import React, { useState, useEffect, useContext } from 'react';
import Rating from '../components/Rating';
import { CartContext } from '../context/CartContext';
import API from '../api';

const INITIAL_DEMO_PRODUCTS = [
  {
    _id: 'prod_001',
    name: 'Aura Wireless Noise-Cancelling Headphones',
    brand: 'AuraAudio',
    category: 'Electronics',
    price: 199.99,
    countInStock: 25,
    rating: 4.8,
    numReviews: 14,
    description: 'High-performance over-ear wireless headphones with active noise cancellation.',
  },
  {
    _id: 'prod_002',
    name: 'Aura Smart Fitness Watch',
    brand: 'AuraTech',
    category: 'Wearables',
    price: 149.99,
    countInStock: 40,
    rating: 4.5,
    numReviews: 9,
    description: 'Water-resistant fitness tracker with heart-rate and sleep monitoring.',
  },
  {
    _id: 'prod_003',
    name: 'Aura Studio Wireless Earbuds',
    brand: 'AuraAudio',
    category: 'Electronics',
    price: 79.99,
    countInStock: 50,
    rating: 4.2,
    numReviews: 6,
    description: 'Compact true-wireless earbuds with charging case and crisp acoustic clarity.',
  },
];

const HomeScreen = ({ onSelectProduct, searchQuery }) => {
  const [products, setProducts] = useState(INITIAL_DEMO_PRODUCTS);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [sortOption, setSortOption] = useState('featured');
  const [loading, setLoading] = useState(false);
  const { addToCart } = useContext(CartContext);

  // Fetch live products from PostgreSQL backend
  useEffect(() => {
    let isMounted = true;
    const fetchCatalog = async () => {
      try {
        setLoading(true);
        const { data } = await API.get('/products');
        if (isMounted && data && Array.isArray(data.products) && data.products.length > 0) {
          setProducts(data.products);
        }
      } catch (err) {
        console.warn('Backend products not loaded, displaying initial store catalog', err.message);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    fetchCatalog();
    return () => { isMounted = false; };
  }, []);

  // Compute dynamic unique categories from live products
  const dynamicCategories = ['All', ...Array.from(new Set(products.map((p) => p.category).filter(Boolean)))];

  // Filtering & Sorting Pipeline
  let filtered = products.filter((p) => {
    const matchesSearch =
      !searchQuery ||
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.brand.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (p.description && p.description.toLowerCase().includes(searchQuery.toLowerCase()));
    const matchesCategory =
      selectedCategory === 'All' || p.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  if (sortOption === 'price_asc') {
    filtered.sort((a, b) => a.price - b.price);
  } else if (sortOption === 'price_desc') {
    filtered.sort((a, b) => b.price - a.price);
  } else if (sortOption === 'rating') {
    filtered.sort((a, b) => b.rating - a.rating);
  }

  return (
    <div style={{ maxWidth: '1280px', margin: '0 auto', padding: '32px 24px' }}>
      {/* Controls Bar: Category Chips & Sort Controls */}
      <div style={{
        display: 'flex',
        flexWrap: 'wrap',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '16px',
        marginBottom: '32px',
      }}>
        {/* Category Pills */}
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {dynamicCategories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              style={{
                padding: '6px 16px',
                borderRadius: '20px',
                border: '1px solid',
                borderColor: selectedCategory === cat ? '#0284c7' : '#e2e8f0',
                backgroundColor: selectedCategory === cat ? '#0284c7' : '#ffffff',
                color: selectedCategory === cat ? '#ffffff' : '#475569',
                fontSize: '13px',
                fontWeight: '600',
                cursor: 'pointer',
                transition: 'all 0.15s ease-in-out',
              }}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Sorting Dropdown */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{ fontSize: '13px', color: '#64748b', fontWeight: '500' }}>Sort By:</span>
          <select
            value={sortOption}
            onChange={(e) => setSortOption(e.target.value)}
            style={{
              padding: '6px 12px',
              borderRadius: '8px',
              border: '1px solid #cbd5e1',
              fontSize: '13px',
              color: '#1e293b',
              backgroundColor: '#ffffff',
              outline: 'none',
              cursor: 'pointer',
            }}
          >
            <option value="featured">Featured</option>
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="rating">Top Rated</option>
          </select>
        </div>
      </div>

      {loading && (
        <div style={{ textAlign: 'center', padding: '24px', color: '#64748b', fontSize: '14px' }}>
          Refreshing product catalog from PostgreSQL...
        </div>
      )}

      {/* Product Grid */}
      {filtered.length === 0 ? (
        <div style={{
          textAlign: 'center',
          padding: '64px 24px',
          backgroundColor: '#f8fafc',
          borderRadius: '16px',
          border: '1px dashed #cbd5e1',
        }}>
          <h3 style={{ margin: 0, fontSize: '18px', color: '#334155' }}>No products found</h3>
          <p style={{ margin: '8px 0 0', fontSize: '14px', color: '#64748b' }}>
            Try clearing your search query or switching categories.
          </p>
        </div>
      ) : (
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
          gap: '24px',
        }}>
          {filtered.map((product) => (
            <div
              key={product._id || product.id}
              style={{
                backgroundColor: '#ffffff',
                borderRadius: '16px',
                border: '1px solid #e2e8f0',
                overflow: 'hidden',
                display: 'flex',
                flexDirection: 'column',
                transition: 'transform 0.2s, box-shadow 0.2s',
              }}
            >
              {/* Image Preview Box */}
              <div
                onClick={() => onSelectProduct && onSelectProduct(product)}
                style={{
                  height: '200px',
                  backgroundColor: '#f1f5f9',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  cursor: 'pointer',
                  position: 'relative',
                }}
              >
                <div style={{
                  fontSize: '11px',
                  fontWeight: '800',
                  color: '#94a3b8',
                  textTransform: 'uppercase',
                  letterSpacing: '0.05em',
                  textAlign: 'center',
                  padding: '12px',
                }}>
                  {product.category} • {product.brand}
                </div>
              </div>

              {/* Product Info */}
              <div style={{ padding: '20px', display: 'flex', flexDirection: 'column', flex: 1 }}>
                <h4
                  onClick={() => onSelectProduct && onSelectProduct(product)}
                  style={{
                    margin: '0 0 8px 0',
                    fontSize: '16px',
                    fontWeight: '700',
                    color: '#0f172a',
                    cursor: 'pointer',
                    lineHeight: '1.4',
                  }}
                >
                  {product.name}
                </h4>

                <div style={{ marginBottom: '12px' }}>
                  <Rating value={product.rating || 0} numReviews={product.numReviews || 0} />
                </div>

                <p style={{
                  margin: '0 0 16px 0',
                  fontSize: '13px',
                  color: '#64748b',
                  lineHeight: '1.5',
                  flex: 1,
                  display: '-webkit-box',
                  WebkitLineClamp: 2,
                  WebkitBoxOrient: 'vertical',
                  overflow: 'hidden',
                }}>
                  {product.description}
                </p>

                {/* Pricing & Cart Action */}
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  marginTop: 'auto',
                  paddingTop: '16px',
                  borderTop: '1px solid #f1f5f9',
                }}>
                  <div>
                    <div style={{ fontSize: '20px', fontWeight: '800', color: '#0f172a' }}>
                      ₹{Number(product.price).toFixed(2)}
  </div>
                    <div style={{
                      fontSize: '11px',
                      fontWeight: '700',
                      color: product.countInStock > 0 ? '#16a34a' : '#dc2626',
                    }}>
                      {product.countInStock > 0 ? `In Stock (${product.countInStock})` : 'Out of Stock'}
                    </div>
                  </div>

                  <button
                    disabled={product.countInStock <= 0}
                    onClick={() => addToCart(product)}
                    style={{
                      backgroundColor: product.countInStock > 0 ? '#0284c7' : '#94a3b8',
                      color: '#ffffff',
                      border: 'none',
                      padding: '8px 16px',
                      borderRadius: '8px',
                      fontWeight: '700',
                      fontSize: '13px',
                      cursor: product.countInStock > 0 ? 'pointer' : 'not-allowed',
                      transition: 'background-color 0.15s ease',
                    }}
                  >
                    Add to Cart
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default HomeScreen;
